//! The benchmark's fixture host (bench profile only): the fixture pages over HTTPS under one name, with a certificate
//! made at start. It writes the certificate's SPKI SHA-256 (base64) to `FIXTURE_SPKI_FILE`, so a bench session's
//! Chromium can accept exactly this certificate and nothing else.
//!
//! `/big?size=N` is a download of N generated bytes (byte i is [`big_byte`]`(i)`), served as fast as the connection
//! takes it, for the large-download tests.
//!
//! Environment: `FIXTURE_NAME` (default `fixture.bench`), `FIXTURE_DIR` (default `/srv/fixtures`), `FIXTURE_LISTEN`
//! (default `0.0.0.0:443`), `FIXTURE_SPKI_FILE` (default `/run/bench/spki`).

use std::sync::Arc;

use base64::Engine;
use rcgen::PublicKeyData;
use sha2::{Digest, Sha256};

fn env(name: &str, default: &str) -> String {
    std::env::var(name).ok().filter(|v| !v.is_empty()).unwrap_or_else(|| default.to_owned())
}

#[tokio::main]
async fn main() -> Result<(), String> {
    let name = env("FIXTURE_NAME", "fixture.bench");
    let dir = env("FIXTURE_DIR", "/srv/fixtures");
    let listen: std::net::SocketAddr =
        env("FIXTURE_LISTEN", "0.0.0.0:443").parse().map_err(|_| "bad FIXTURE_LISTEN")?;
    let certified = rcgen::generate_simple_self_signed(vec![name.clone()]).map_err(|e| e.to_string())?;
    let spki = Sha256::digest(certified.signing_key.subject_public_key_info());
    let spki = base64::engine::general_purpose::STANDARD.encode(spki);
    std::fs::write(env("FIXTURE_SPKI_FILE", "/run/bench/spki"), &spki).map_err(|e| e.to_string())?;
    let cert = certified.cert.der().clone();
    let key = rustls::pki_types::PrivateKeyDer::Pkcs8(certified.signing_key.serialize_der().into());
    let provider = Arc::new(rustls::crypto::ring::default_provider());
    let mut config = rustls::ServerConfig::builder_with_provider(provider)
        .with_safe_default_protocol_versions()
        .map_err(|e| e.to_string())?
        .with_no_client_auth()
        .with_single_cert(vec![cert], key)
        .map_err(|e| e.to_string())?;
    config.alpn_protocols = vec![b"http/1.1".to_vec()];
    println!("fixture host {name} on {listen}, SPKI sha256/{spki}");
    let app = axum::Router::new()
        .route("/big", axum::routing::get(big))
        .route("/accept-language", axum::routing::get(accept_language))
        .fallback_service(tower_http::services::ServeDir::new(dir));
    axum_server::bind_rustls(listen, axum_server::tls_rustls::RustlsConfig::from_config(Arc::new(config)))
        .serve(app.into_make_service())
        .await
        .map_err(|e| e.to_string())
}

/// The request's Accept-Language header, which the stealth probe compares with navigator.languages.
async fn accept_language(headers: axum::http::HeaderMap) -> String {
    headers.get("accept-language").and_then(|v| v.to_str().ok()).unwrap_or_default().to_owned()
}

/// Byte `i` of every `/big` download.
fn big_byte(i: u64) -> u8 {
    (i.wrapping_mul(7) ^ (i >> 8) ^ (i >> 24)) as u8
}

#[derive(serde::Deserialize)]
struct Big {
    size: u64,
}

async fn big(axum::extract::Query(Big { size }): axum::extract::Query<Big>) -> axum::response::Response {
    const PIECE: u64 = 1 << 20;
    let pieces = futures_util::stream::unfold(0u64, move |at| async move {
        if at >= size {
            return None;
        }
        let end = (at + PIECE).min(size);
        let bytes: Vec<u8> = (at..end).map(big_byte).collect();
        Some((Ok::<_, std::io::Error>(axum::body::Bytes::from(bytes)), end))
    });
    axum::response::Response::builder()
        .header("content-type", "application/octet-stream")
        .header("content-length", size)
        .header("content-disposition", "attachment; filename=\"big.bin\"")
        .body(axum::body::Body::from_stream(pieces))
        .unwrap_or_default()
}
